mapper.select:
SELECT DATE_FORMAT(o.order_time, '%Y-%m-%d') as day, SUM(o.amount) as dailyTotal
FROM orders o
WHERE o.user_id = #{userId}
  AND o.order_time >= #{startTime}
  AND o.order_time <= #{endTime}
  AND o.pay_status = 1
  AND o.status != 6
GROUP BY day
ORDER BY day ASC

SELECT o.order_time
FROM orders o
WHERE o.user_id = #{userId}
  AND o.order_time >= #{startTime}
  AND o.order_time <= #{endTime}
  AND o.pay_status = 1
  AND o.status != 6
ORDER BY o.order_time ASC
